package com.domesticservice.catalog;
import com.domesticservice.catalog.service.RecoveryVoucherService;import com.domesticservice.catalog.repository.support.NativeQueryExecutor;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.autoconfigure.EnableAutoConfiguration;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.context.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="DISCIPLINE_POSTGRES_VERIFY",matches="true")
@SpringBootTest(classes=RecoveryVoucherPostgresTests.Config.class,webEnvironment=SpringBootTest.WebEnvironment.NONE,properties={"spring.datasource.url=jdbc:postgresql://localhost:5549/discipline_catalog","spring.datasource.username=postgres","spring.datasource.password=discipline_test_only","spring.jpa.hibernate.ddl-auto=none","spring.flyway.enabled=true","clients.identity.base-url=http://127.0.0.1:1","INTERNAL_SERVICE_TOKEN=isolated-key"})
class RecoveryVoucherPostgresTests {
 @Configuration(proxyBeanMethods=false) @EnableAutoConfiguration @Import({NativeQueryExecutor.class,RecoveryVoucherService.class}) static class Config {}
 @Autowired RecoveryVoucherService vouchers;@Autowired JdbcTemplate db;
 @Test void personalizedFivePercentVoucherIsIssuedOncePerForgottenBooking(){long booking=System.nanoTime();var b=Map.<String,Object>of("bookingId",booking,"customerId",101);var first=vouchers.issue(b);assertEquals(first.get("id"),vouchers.issue(b).get("id"));assertEquals(5,((Number)first.get("discount_value")).intValue());assertEquals(1,((Number)first.get("usage_limit")).intValue());assertEquals(101,((Number)first.get("owner_customer_id")).intValue());assertThrows(Exception.class,()->vouchers.issue(Map.of("bookingId",booking,"customerId",102)));}
 @Test void internalEndpointRejectsInvalidSecrets(){assertThrows(Exception.class,()->vouchers.authorize(null));assertThrows(Exception.class,()->vouchers.authorize("wrong"));assertDoesNotThrow(()->vouchers.authorize("isolated-key"));}
}
